      }), _jsxs(_components.p, {
        children: ["The maps available in the Maps1 folder plot isobars (lines of equal atmospheric pressure) as well as wind (white lines), considered at 0 elevation about the ground level. The pressure difference between two isobars is ", _jsx(MATHSPAN, {
